const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let lang='ru',variant='split',hasPair=true,menuContext=null,menuOpener=null,toastTimer;
const state={},authors={},drafts={},events={};
const L=(ru,en)=>lang==='ru'?ru:en;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=k=>I[k]||I.plus;
const photo=(n,alt='')=>`<img src="images/profile-${n}-45.webp" alt="${esc(alt)}" loading="lazy">`;
const contentPhoto=(name,alt)=>`<img src="images/v10-content/${name}.webp" alt="${esc(alt)}" loading="lazy">`;
const avatar=(who='me',cls='')=>`<span class="avatar ${who==='couple'?'pair':''} ${cls}" aria-hidden="true">${who==='couple'?photo(8)+photo(4):photo(who==='me'?8:who)}</span>`;
const short=who=>who==='me'?L('Я','Me'):L('Мы','Us');
const name=who=>who==='me'?'Alex':'Alex & Eva';
const by=who=>who==='me'?L('от себя','as yourself'):L('от пары','as your couple');
const owner=context=>hasPair?(authors[context]||'me'):'me';
const active=(id,who)=>!!state[id]?.[who];
const op={
 follow:{icon:'plus',off:()=>L('Подписаться','Follow'),on:()=>L('Подписаны','Following'),status:()=>L('Уже подписаны','Already following')},
 like:{icon:'heart',off:()=>L('Нравится','Like'),on:()=>L('Нравится','Liked'),status:()=>L('Симпатия отправлена','Like sent')},
 request:{icon:'key',off:()=>L('Доступ','Request'),on:()=>L('Запрошен','Requested'),status:()=>L('Запрос отправлен','Request sent')},
 send:{icon:'send',off:()=>L('Отправить','Send'),on:()=>L('Отправлено','Sent'),status:()=>L('Можно отправить ещё','Ready to send again')},
 publish:{icon:'plus',off:()=>L('Опубликовать','Publish'),on:()=>L('Опубликовано','Published'),status:()=>L('Публикация создана','Post published')}
};
const actions={
 'profile-like':{context:'profile',type:'like',primary:true},'profile-follow':{context:'profile',type:'follow'},'profile-request':{context:'profile',type:'request',compact:true},
 'post-like':{context:'post',type:'like',compact:true,count:24},'comment-like':{context:'comments',type:'like',compact:true,count:2},'reply-send':{context:'comments',type:'send',primary:true,input:'reply-text'},
 'dating-like':{context:'dating',type:'like',primary:true,circle:true},'publish':{context:'compose',type:'publish',primary:true,input:'post-text'},
 'access-request':{context:'access',type:'request',primary:true,label:()=>L('Запросить доступ','Request access')},
 'list-follow':{context:'lists',type:'follow'},'search-follow':{context:'search',type:'follow'},'notification-follow':{context:'notification',type:'follow'},
 'discussion-like':{context:'discussion',type:'like',compact:true,count:18},'discussion-send':{context:'discussion',type:'send',primary:true,input:'discussion-text'},
 'poll-vote':{context:'poll',type:'send',label:()=>L('Проголосовать','Vote'),primary:true}
};
function actionLabel(id,who){const a=actions[id],o=op[a.type];if(a.count!=null)return String(a.count+['me','couple'].filter(x=>active(id,x)).length);return active(id,who)?o.on():(a.label?a.label():o.off());}
function actionIcon(id,who){const a=actions[id];return active(id,who)?(a.type==='like'?icon('heartf'):icon('check')):icon(op[a.type].icon);}
function action(id){const a=actions[id],who=owner(a.context),on=active(id,who),label=actionLabel(id,who);const classes=`action ${a.compact?'compact':''} ${a.primary?'primary':''} ${a.circle?'circle':''} ${on?'active':''}`;
 const title=`${op[a.type].off()} ${by(who)}`;
 if(!hasPair)return `<div class="${classes}"><button class="fire" data-fire="${id}" aria-label="${esc(title)}" ${['like','follow'].includes(a.type)?`aria-pressed="${on}"`:''}>${actionIcon(id,who)}${a.circle?'':`<span>${esc(label)}</span>`}</button></div>`;
 if(variant==='gesture')return gestureAction(id,classes);
 if(variant==='dual')return `<div class="dual-wrap">${a.compact||a.circle?'':`<p class="dual-label">${esc(a.label?a.label():op[a.type].off())}</p>`}<div class="${classes}">${['me','couple'].map(w=>`<button class="dual-fire ${active(id,w)?'on':''}" data-fire="${id}" data-who="${w}" aria-label="${esc(op[a.type].off()+' '+by(w))}" aria-pressed="${active(id,w)}">${avatar(w)}<span>${short(w)}</span>${actionIcon(id,w)}</button>`).join('')}</div></div>`;
 const chooser=variant==='choose';
 return `<div class="${classes}"><button class="fire" ${chooser?`data-menu="${id}"`:`data-fire="${id}"`} aria-label="${esc(chooser?L('Выбрать автора: ','Choose identity: ')+title:title)}" ${chooser?'aria-haspopup="dialog"':`aria-pressed="${on}"`}>${actionIcon(id,who)}${a.circle?'':`<span>${esc(label)}</span>`}${chooser?avatar(who,'small'):''}${chooser?icon('down'):''}</button>${chooser?'':`<button class="identity" data-menu="${id}" aria-label="${esc(L('Изменить автора: ','Change identity: ')+name(who))}" aria-haspopup="dialog">${avatar(who)}${a.compact||a.circle?'':`<span class="who">${short(who)}</span>`}${icon('down')}</button>`}</div>`;
}
const slot=id=>`<span data-slot="${id}">${action(id)}</span>`;
const fixed=(who='me')=>`<span class="fixed-author">${avatar(who,'small')}${short(who)} · ${name(who)}${icon('lock')}</span>`;
const normal=(text,key,primary=false)=>`<button class="standard-btn ${primary?'primary':''}" data-local="${key}">${text}</button>`;
function specimen(id,num,title,body,note,tag=''){return `<section class="specimen" id="${id}"><div class="spec-label"><span class="num">${num}</span><h2>${title}</h2>${tag?`<span class="tag">${tag}</span>`:''}</div><div class="fragment">${body}</div><p class="caption">${note}</p></section>`;}
function render(){
 cancelGesture();
 // Preserve locally typed drafts when changing a mechanism, identity, or display setting.
 $$('textarea').forEach(t=>drafts[t.id]=t.value);
 const checkedPoll=$('input[name=poll]:checked');if(checkedPoll)events.poll=checkedPoll.value;
 document.body.classList.toggle('no-pair',!hasPair);document.body.classList.toggle('variant-dual',variant==='dual');document.body.classList.toggle('variant-gesture',variant==='gesture');$('#gesture-guide').hidden=variant!=='gesture'||!hasPair;
 $$('[data-ru]').forEach(e=>e.innerHTML=e.dataset[lang]);$('#lang').textContent=lang==='ru'?'EN':'RU';document.documentElement.lang=lang;
 $$('[data-variant]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.variant===variant));$('#pair-toggle').setAttribute('aria-checked',hasPair);
 const notes={gesture:L('Касание — от показанного автора. Удержание 280 мс и движение вверх / вниз — выбор и действие при отпускании. Лайки и подписки у каждого автора свои.','Tap to act as the shown identity. Hold for 280 ms, move up / down, then release. Each identity has independent likes and follows.'),split:L('Основная часть выполняет действие. Аватарка со стрелкой меняет автора — без выполнения действия.','The main part performs the action. The avatar and arrow change identity without performing it.'),choose:L('Нажатие открывает два варианта. Выбор «Я» или «Мы» сразу выполняет действие.','Tap to see both identities. Choosing Me or Us immediately performs the action.'),dual:L('Оба автора и оба состояния видны сразу. Нажатие на «Я» или «Мы» выполняет действие.','Both identities and their states are visible. Tap Me or Us to perform the action.')};
 $('#mechanic-note').textContent=hasPair?notes[variant]:L('Пары нет: обычные кнопки, без аватарок автора, «Я / Мы» и лишних стрелок.','No active couple: ordinary buttons, without identity avatars, Me / Us labels or extra arrows.');
 const authorC=owner('comments'),authorP=owner('compose'),authorD=owner('discussion');
 const cards=[];
 cards.push(specimen('profile','01',L('Профиль человека','Member profile'),`<div class="profile-photo">${photo(1,'Mia')}<span class="photo-back">${icon('back')}</span><div class="profile-meta"><h3>Mia, 29</h3><p>${L('Берлин · в сети','Berlin · online')}</p><div class="chips"><span class="chip">${L('Полиамория','Polyamory')}</span><span class="chip">${L('Свидания','Dating')}</span><span class="chip">${L('Шибари','Shibari')}</span></div></div></div><div class="fragment-inner"><div class="actions-wrap profile-actions">${slot('profile-like')}${slot('profile-follow')}${slot('profile-request')}</div><div class="compat"><b>4</b><span>${L('Общие темы<br>Есть с чего начать разговор','Shared interests<br>A good place to start a conversation')}</span></div><div class="subsection">${L('О СЕБЕ','ABOUT')}</div><p class="bio">${L('Люблю людей, с которыми можно говорить прямо и никуда не торопиться.','I like people who speak openly and take their time.')}</p></div>`,L('Один автор для действий в этом профиле. Выбор на любой кнопке обновляет остальные.','One identity for this profile. Changing it on any button updates the others.'),L('Общий контекст','Shared context')));
 cards.push(specimen('post','02',L('Публикация в ленте','Post in the feed'),`<div class="post-head row">${avatar(2)}<div class="grow"><div class="display-name">Sofi</div><div class="meta-line">${L('2 часа назад · Берлин','2 hours ago · Berlin')}</div></div><span class="plain-icon">${icon('more')}</span></div><p class="post-text">${L('Утренний кофе после длинного разговора. Как же ценно, когда тебя слышат.','Morning coffee after a long conversation. Being heard really matters.')}</p><div class="post-media">${contentPhoto('post-p7-morning-coffee','Coffee')}</div><div class="post-foot">${slot('post-like')}<button class="plain-icon" data-scroll="comments" aria-label="${L('Открыть ответы','Open replies')}">${icon('chat')}<span>6</span></button><button class="plain-icon" data-local="save" aria-label="${L('Сохранить','Save')}">${icon('bookmark')}</button><button class="plain-icon" data-local="share" aria-label="${L('Поделиться','Share')}">${icon('share')}</button></div>`,L('Сердце ставит лайк. Маленькая аватарка рядом выбирает автора. Сохранить и поделиться не требуют выбора пары.','The heart likes the post. The adjacent avatar selects identity. Save and share do not need a couple selector.')));
 cards.push(specimen('comments','03',L('Комментарии и ответ','Comments and reply'),`<div class="mini-bar">${L('Ответы','Replies')} <span class="muted">6</span></div><div class="comment"><div class="row">${avatar(3)}<div class="grow"><b class="display-name">Kai</b><div class="meta-line">${L('18 минут назад','18 minutes ago')}</div></div></div><p>${L('Да! Иногда лучший вечер — просто разговор без ожиданий.','Yes! Sometimes the best evening is a conversation with no expectations.')}</p><div class="comment-actions">${slot('comment-like')}<button class="text-link" data-focus="reply-text">${L('Ответить','Reply')}</button></div></div><div class="composer"><div class="composer-head">${avatar(authorC,'small')}<span>${L('Ответ','Reply')} · <b>${hasPair?name(authorC):'Alex'}</b></span></div><textarea id="reply-text" aria-label="${L('Текст ответа','Reply text')}" placeholder="${L('Ответить Kai…','Reply to Kai…')}">${esc(drafts['reply-text']||'')}</textarea><div class="composer-foot"><span class="muted tiny">${L('В ветке обсуждения','In this thread')}</span>${slot('reply-send')}</div></div>`,L('Лайк и отправка ответа используют автора этой ветки. Над текстом сразу видно, чья аватарка появится рядом с ответом.','Likes and replies use the identity selected for this thread. The composer shows whose avatar will appear.')));
 cards.push(specimen('dating','04',L('Знакомства: кнопки и жесты','Dating: buttons and gestures'),`<div class="mini-bar">${L('Люди','People')}<span class="plain-icon">${icon('filter')}</span></div><div class="tabs"><b>${L('Подборка','Discover')}</b><span>${L('Симпатии','Likes')}</span><span>${L('Просмотренные','Viewed')}</span></div><div class="deck">${photo(3,'Kai')}<div class="deck-caption"><h3>Kai, 31</h3><p>${L('Берлин · в 3 км','Berlin · 3 km away')}</p><div class="chips"><span class="chip">${L('Любопытство','Curiosity')}</span><span class="chip">${L('Открытость','Openness')}</span></div></div></div><div class="deck-actions"><button class="skip" data-local="skip" aria-label="${L('Пропустить анкету','Skip profile')}">${icon('close')}</button>${slot('dating-like')}</div><div class="deck-context">${hasPair?L('Кнопка и свайп вправо — ','Button and swipe right — ')+by(owner('dating')):L('Личная подборка','Your discover feed')}</div>`,L('У выбора автора есть последствия: подпись объясняет, от кого уйдёт и лайк кнопкой, и свайп. Пропуск не является действием от пары.','The caption names the sender for both button likes and swipes. Skipping does not act on behalf of the couple.')));
 cards.push(specimen('compose','05',L('Новая публикация','New post'),`<div class="mini-bar">${L('Новая публикация','New post')}<span class="muted tiny">${L('Черновик','Draft')}</span></div><div class="fragment-inner"><div class="row">${avatar(authorP)}<div><b class="display-name">${name(authorP)}</b><div class="meta-line">${L('Всем','Everyone')}</div></div></div><textarea id="post-text" class="editor-text" aria-label="${L('Текст публикации','Post text')}" style="width:100%;border:0;background:transparent;resize:vertical">${esc(drafts['post-text']??L('Хотим собрать небольшой круг для разговоров о границах. Кто с нами?','We would love to gather a small circle to talk about boundaries. Who is in?'))}</textarea><div class="attachment">${contentPhoto('event-e2-boundaries-circle','Circle')}</div><div class="row muted">${icon('image')}${icon('poll')}${icon('tag')}</div></div><div class="editor-foot full-action">${slot('publish')}</div>`,L('Кнопка и шапка редактора показывают одного автора. Переключение сохраняет текст и вложение.','The button and composer header show the same identity. Switching keeps the draft and attachment.')));
 cards.push(specimen('access','06',L('Запрос расширенного профиля','Private profile request'),`<div class="fragment-inner"><div class="lock-heading"><span>${icon('lock')}</span><div><h3>${L('Познакомиться ближе','Get to know more')}</h3><div class="meta-line">${L('Расширенный профиль Mia','Mia’s private profile')}</div></div></div><p class="body-copy">${L('Личные интересы и фотографии — только с разрешения Mia. Она сама решит, что открыть и на какой срок.','Personal interests and photos are shared with Mia’s permission. She chooses what to share and for how long.')}</p><div class="note-strip">${L('Запрос от пары увидит Mia. Открытый паре доступ предназначен обоим участникам.','Mia will see a request from your couple. Access granted to the couple is intended for both partners.')}</div><div class="full-action">${slot('access-request')}</div></div>`,L('В меню видно, отправлен ли запрос от каждого автора. Выбор автора не открывает доступ автоматически.','The menu shows request status for each identity. Changing identity never grants access.')));
 cards.push(specimen('lists','07',L('Подписки и подписчики','Following and followers'),`<div class="follow-header">${L('Подписки','Following')} <span class="muted">24</span></div><div class="list-row">${avatar(1)}<div class="grow"><b class="display-name">Mia</b><div class="meta-line">${L('Берлин','Berlin')}</div></div>${slot('list-follow')}</div><div class="list-row">${avatar(3)}<div class="grow"><b class="display-name">Kai</b><div class="meta-line">${L('Подписан на тебя','Follows you')}</div></div>${normal(L('Профиль','Profile'),'profile')}</div><div class="fragment-inner"><p class="body-copy">${L('Личная подписка и подписка пары существуют отдельно.','Personal and couple follows are independent.')}</p></div>`,L('Можно увидеть: лично уже подписан, от пары — ещё нет. Повторное нажатие снимает подписку только выбранного автора.','You may already follow personally while the couple does not. Unfollowing affects only the chosen identity.')));
 cards.push(specimen('search','08',L('Поиск людей','People search'),`<div class="mini-bar">${L('Поиск','Search')}${icon('close')}</div><div class="search-box">${icon('search')}<span>Mia</span></div><div class="tabs"><b>${L('Люди','People')}</b><span>${L('Публикации','Posts')}</span><span>${L('Сообщества','Communities')}</span></div><div class="list-row">${avatar(1)}<div class="grow"><b class="display-name">Mia</b><div class="meta-line">${L('Берлин · 29','Berlin · 29')}</div></div>${slot('search-follow')}</div><div class="fragment-inner"><p class="body-copy">${L('Знакомая кнопка в короткой строке результата. Не нужно сначала открывать профиль.','The same control in a compact result row. No need to open the profile first.')}</p></div>`,L('Выбор автора работает прямо в строке. Длинное имя переносится, кнопка остаётся доступной.','Identity can be changed right in the row. Long names wrap while the action stays accessible.')));
 cards.push(specimen('notification','09',L('Уведомления','Notifications'),`<div class="mini-bar">${L('Уведомления','Notifications')}<span class="muted tiny">${L('Все прочитаны','All read')}</span></div><div class="notify-body"><div class="row">${avatar(2,'large')}<div><b class="display-name">Sofi</b><div class="meta-line">${L('5 минут назад','5 minutes ago')}</div></div></div><p>${L('<b>Sofi подписалась на тебя.</b><br>Вам интересны забота и открытые разговоры.','<b>Sofi followed you.</b><br>You share an interest in care and open conversation.')}</p>${slot('notification-follow')}</div>`,L('Ответная подписка — такое же действие с выбором автора. Входящее уведомление остаётся адресованным тебе.','Following back uses the same identity control. The original notification remains addressed to you.')));
 cards.push(specimen('discussion','10',L('Обсуждение в сообществе','Community discussion'),`<div class="mini-bar">${L('Узлы и разговоры','Knots & conversations')}</div><div class="fragment-inner"><div class="row">${avatar(5)}<div><b class="display-name">Noah</b><div class="meta-line">${L('Сегодня, 10:20','Today, 10:20')}</div></div></div><h3 style="margin-top:16px">${L('Как договориться о паузе?','How do you ask for a pause?')}</h3><p class="body-copy">${L('Какие фразы помогают вам остановиться и проверить, всё ли комфортно?','What phrases help you stop and check whether everyone feels comfortable?')}</p>${slot('discussion-like')}</div><div class="composer"><div class="composer-head">${avatar(authorD,'small')}<span>${L('Ответ от','Reply from')} <b>${name(authorD)}</b></span></div><textarea id="discussion-text" aria-label="${L('Ответ в обсуждении','Discussion reply')}" placeholder="${L('Поделись опытом…','Share your experience…')}">${esc(drafts['discussion-text']||'')}</textarea><div class="composer-foot"><span class="tiny muted">${L('В обсуждение','To the discussion')}</span>${slot('discussion-send')}</div></div>`,L('<strong>Вариант для обсуждения:</strong> если разрешим ответы от пары, механика будет такой же. Вступление и участие ниже остаются личными.','<strong>Optional direction:</strong> if couple replies are enabled, they can use the same control. Membership and event participation below stay personal.'),L('На обсуждение','For discussion')));
 cards.push(specimen('poll','11',L('Опрос в ленте','Feed poll'),`<div class="post-head row">${avatar(4)}<div><b class="display-name">Eva</b><div class="meta-line">${L('Вчера','Yesterday')}</div></div></div><div class="fragment-inner"><h3>${L('Первое знакомство — где?','Where would you first meet?')}</h3>${['coffee','walk','event'].map((k,i)=>`<label class="row" style="padding:10px 0;font-size:12px"><input type="radio" name="poll" value="${k}" ${(events.poll||'coffee')===k?'checked':''}>${[L('Кофе и разговор','Coffee and a chat'),L('Прогулка','A walk'),L('Небольшое событие','A small event')][i]}</label>`).join('')}<div class="full-action" style="margin-top:14px">${slot('poll-vote')}</div></div>`,L('<strong>На обсуждение:</strong> отдельный голос пары — продуктовая опция. Здесь показано, как он выглядел бы; правила голосования прототипа не изменены.','<strong>For discussion:</strong> a separate couple vote is a product option. This shows how it could look; the prototype’s voting rules are unchanged.'),L('На обсуждение','For discussion')));
 cards.push(specimen('fixed','12',L('Чат: автор фиксирован','Chat: fixed identity'),`<div class="mini-bar"><div class="row">${avatar(1)}<div>Mia<div class="meta-line">${(hasPair?L('Чат с парой Alex & Eva','Chat with Alex & Eva'):L('Личный чат с Alex','Personal chat with Alex'))}</div></div></div>${icon('lock')}</div><div class="fragment-inner">${fixed(hasPair?'couple':'me')}<div class="bubble">${L('Можем встретиться в субботу?','Can we meet on Saturday?')}</div><div class="bubble mine">${(hasPair?L('Да, нам удобно после четырёх.','Yes, after four works for us.'):L('Да, мне удобно после четырёх.','Yes, after four works for me.'))}</div><p class="tiny muted">${hasPair?L('Участники: Mia, Alex, Eva','Participants: Mia, Alex, Eva'):L('Участники: Mia, Alex','Participants: Mia, Alex')}</p></div><div class="chat-input">${avatar(hasPair?'couple':'me','small')}<input aria-label="${L('Сообщение в чате','Chat message')}" placeholder="${L('Сообщение…','Message…')}"><button data-local="chat-send" aria-label="${L('Отправить сообщение','Send message')}">${icon('send')}</button></div>`,L('В существующем чате нельзя подменить состав участников переключателем. Видно, от чьего имени пишешь, но стрелки выбора нет.','An existing chat’s participants cannot be changed through an identity selector. The sender is visible, without a dropdown.')));
 cards.push(specimen('membership','13',L('Вступление в сообщество','Joining a community'),`<div class="community-cover">${contentPhoto('community-slow','Community')}<h3>${L('Медленные знакомства','Slow connections')}</h3></div><div class="fragment-inner"><p class="body-copy">${L('Для тех, кому важнее разговор и внимание, чем скорость.','For people who value conversation and attention over speed.')}</p><div class="fixed-actions">${fixed()}${normal(L('Вступить','Join'),'join',true)}</div></div>`,L('По текущему решению MVP в сообщества вступают лично. Выбор пары не предлагаем.','Under the current MVP rules, people join communities personally. There is no couple selector.'),L('Без выбора','Fixed identity')));
 cards.push(specimen('rsvp','14',L('Участие в событии','Event attendance'),`<div class="event-line"><span class="date-tile">${L('ОКТ','OCT')}<b>24</b></span><div><h3>${L('Кофе без спешки','Coffee, unhurried')}</h3><span class="meta-line">${L('Берлин · 16:00','Berlin · 4:00 PM')}</span></div></div><div class="fragment-inner"><div class="row" style="justify-content:space-between;margin-bottom:16px"><b style="font-size:12px">${L('Пойдёшь?','Will you attend?')}</b>${fixed()}</div><div class="rsvp">${['interested','going'].map((k,i)=>normal([L('Интересно','Interested'),L('Иду','Going')][i],k,i===1)).join('')}</div><p class="tiny muted" style="margin-bottom:0">${L('Ответ видит организатор. Видимость можно изменить.','The organizer can see your response. Visibility can be changed.')}</p></div>`,L('Участие относится к конкретному человеку. Партнёр подтверждает своё участие самостоятельно.','Attendance belongs to an individual. Your partner confirms their own attendance.'),L('Без выбора','Fixed identity')));
 cards.push(specimen('grants','15',L('Решение о доступе','Granting access'),`<div class="mini-bar">${L('Запросы ко мне','Requests to me')}${icon('key')}</div><div class="fragment-inner"><div class="row">${avatar(1)}<div><b class="display-name">Mia</b><div class="meta-line">${L('Просит расширенный профиль','Requests your private profile')}</div></div></div><p class="body-copy">${L('Запрос адресован личному профилю Alex. Открываешь только свои разделы.','This request is addressed to Alex’s personal profile. You can only grant access to your own sections.')}</p>${fixed()}<div class="actions-wrap" style="margin-top:16px">${normal(L('Не сейчас','Not now'),'decline')}${normal(L('Выбрать доступ','Choose access'),'grant',true)}</div></div>`,L('Владелец данных уже задан запросом. Менять «Я / Мы» на кнопке одобрения нельзя.','The request already identifies the data owner. An approval button cannot switch that owner.'),L('Без выбора','Fixed identity')));
 $('#gallery').innerHTML=cards.join('');
}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('on'),3300);}
function rememberDrafts(){$$('textarea').forEach(t=>drafts[t.id]=t.value);}
function perform(id,who){const a=actions[id];if(!a)return;who=hasPair?(who||owner(a.context)):'me';rememberDrafts();if(a.input&&!drafts[a.input]?.trim()){notify(L('Сначала напиши текст','Write something first'));$('#'+a.input)?.focus();return;}
 if(id==='poll-vote')events.poll=$('input[name=poll]:checked')?.value||'coffee';
 state[id]??={};const before=!!state[id][who];state[id][who]=['follow','like','request'].includes(a.type)?!before:true;
 const messages={follow:before?L('Подписка снята','Unfollowed'):L('Подписка оформлена','Following'),like:before?L('Лайк убран','Like removed'):L('Лайк поставлен','Liked'),request:before?L('Запрос отменён','Request cancelled'):L('Запрос отправлен','Request sent'),send:id==='poll-vote'?L('Голос учтён','Vote recorded'):L('Ответ отправлен','Reply sent'),publish:L('Публикация создана','Post published')};
 if(a.input&&a.type==='send'){drafts[a.input]='';const el=$('#'+a.input);if(el)el.value='';}
 render();notify(messages[a.type]+' · '+by(who));
}
function closeMenu(restore=true){if($('#author-menu').hidden)return;$('#author-menu').hidden=true;$('#menu-scrim').hidden=true;$$('[data-menu]').forEach(b=>b.setAttribute('aria-expanded','false'));if(restore&&menuOpener?.isConnected)menuOpener.focus({preventScroll:true});menuContext=null;}
function openMenu(id,opener){if(!hasPair)return;closeMenu(false);const a=actions[id],who=owner(a.context),immediate=variant==='choose';menuContext={id,immediate};menuOpener=opener;
 $('#author-menu').innerHTML=`<div class="menu-title"><span>${immediate?L('От чьего имени выполнить?','Who should perform this?'):L('От чьего имени?','Choose identity')}</span><button class="plain-icon" data-close aria-label="${L('Закрыть','Close')}">${icon('close')}</button></div>${['me','couple'].map(w=>`<button class="menu-row ${w===who?'chosen':''}" data-pick="${w}">${avatar(w)}<span class="grow"><b class="display-name">${short(w)} · ${name(w)}</b><span class="meta-line" style="display:block">${active(id,w)?op[a.type].status():immediate?(a.label?a.label():op[a.type].off()):w==='me'?L('Личный профиль','Personal profile'):L('Общий профиль пары','Couple profile')}</span></span>${w===who?icon('check'):''}</button>`).join('')}<div class="menu-hint">${immediate?L('Нажатие на автора сразу выполнит действие.','Choosing an identity performs the action immediately.'):L('Выбор только меняет автора. Действие выполни кнопкой.','This only changes identity. Use the action button to continue.')}</div>`;
 $('#author-menu').hidden=false;$('#menu-scrim').hidden=false;opener.setAttribute('aria-expanded','true');
 const r=opener.getBoundingClientRect(),m=$('#author-menu'),w=m.offsetWidth,h=m.offsetHeight,viewH=window.visualViewport?.height||innerHeight;
 m.style.left=Math.min(Math.max(12,r.right-w),innerWidth-w-12)+'px';m.style.top=Math.max(12,r.bottom+h+10<viewH?r.bottom+8:r.top-h-8)+'px';m.querySelector('[data-pick="'+who+'"]').focus({preventScroll:true});
}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(e.target.id==='menu-scrim'){closeMenu();return;}if(!b)return;
 if(b.dataset.variant){closeMenu(false);variant=b.dataset.variant;render();return;}
 if(b.id==='pair-toggle'){closeMenu(false);hasPair=!hasPair;render();return;}
 if(b.id==='theme'){const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';b.setAttribute('aria-label',dark?L('Светлая тема','Light theme'):L('Тёмная тема','Dark theme'));return;}
 if(b.id==='lang'){closeMenu(false);lang=lang==='ru'?'en':'ru';render();return;}
 if(b.id==='reset'){closeMenu(false);for(const k of Object.keys(state))delete state[k];for(const k of Object.keys(authors))delete authors[k];for(const k of Object.keys(drafts))delete drafts[k];$$('textarea').forEach(t=>t.value='');state['list-follow']={me:true};render();notify(L('Действия и авторы сброшены','Actions and identities reset'));return;}
 if(b.dataset.close!==undefined){closeMenu();return;}
 if(b.dataset.menu){openMenu(b.dataset.menu,b);return;}
 if(b.dataset.pick){const ctx=menuContext;if(!ctx)return;const w=b.dataset.pick;authors[actions[ctx.id].context]=w;closeMenu(false);if(ctx.immediate)perform(ctx.id,w);else{render();const slot=document.querySelector('[data-slot="'+ctx.id+'"]');slot?.querySelector('[data-menu]')?.focus({preventScroll:true});notify(L('Автор выбран: ','Identity selected: ')+name(w));}return;}
 if(b.dataset.fire){perform(b.dataset.fire,b.dataset.who);return;}
 if(b.dataset.scroll){document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});return;}
 if(b.dataset.focus){document.getElementById(b.dataset.focus)?.focus();return;}
 if(b.dataset.local){const k=b.dataset.local;if(k==='chat-send'){const input=$('.chat-input input');if(!input.value.trim()){input.focus();return;}input.value='';notify(L('Сообщение отправлено в текущий чат','Message sent in the current chat'));return;}if(['interested','going','join'].includes(k)){b.classList.toggle('primary');b.setAttribute('aria-pressed',b.classList.contains('primary'));notify(L('Личное действие · Alex','Personal action · Alex'));}else notify(({save:L('Сохранено в личное','Saved personally'),share:L('Открыт выбор способа поделиться','Share options opened'),skip:L('Анкета пропущена','Profile skipped'),profile:L('Здесь откроется профиль Kai','Kai’s profile opens here'),decline:L('Запрос оставлен без ответа','Request left unanswered'),grant:L('Доступ к личному профилю Alex','Access to Alex’s personal profile')})[k]||L('Действие выполнено','Done'));}
});
document.addEventListener('keydown',e=>{if($('#author-menu').hidden)return;if(e.key==='Escape'){e.preventDefault();closeMenu();}if(e.key==='Tab'){const nodes=[...$('#author-menu').querySelectorAll('button')];const i=nodes.indexOf(document.activeElement);if(e.shiftKey&&i===0){e.preventDefault();nodes.at(-1).focus();}else if(!e.shiftKey&&i===nodes.length-1){e.preventDefault();nodes[0].focus();}}});
window.addEventListener('resize',()=>closeMenu());
state['list-follow']={me:true};
render();
